{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have encryption enabled for its root block device, potentially exposing stored data."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP.",
      "resource": "aws_instance.ubuntu[1]",
      "severity": "MEDIUM",
      "explanation": "One of the EC2 instances is assigned a public IP address, potentially exposing it to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance has IMDSv1 enabled, which can be used to access instance metadata and potentially leak sensitive information."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = ( count.index == 1 ? false : false)\n  subnet_id = aws_subnet.my_subnet.id\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Disabled public IP for the instance at index 1, enabled IMDSv2 by requiring HTTP tokens, and enabled encryption for the root block device."
}
